<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { api } from './api'
import * as XLSX from 'xlsx'
import { jsPDF } from 'jspdf'
import autoTable from 'jspdf-autotable'
const props=defineProps({channel:{type:String,default:'telegram'}})
const isTelegram=computed(()=>props.channel==='telegram')
const channelLabel=computed(()=>isTelegram.value?'Telegram':'WhatsApp')
const broadcasts=ref([]),bots=ref([]),whatsappConnections=ref([]),audience=ref([]),fields=ref([]),mediaAssets=ref([]),segments=ref([]),templates=ref([]),selected=ref(null),loading=ref(false),saving=ref(false),uploadingMedia=ref(false),error=ref(''),success=ref('')
const form=ref({name:'',channel_account_id:'',message_text:'',message_mode:'freeform',provider_template:null,audience_type:'all',contact_ids:[],audience_filter:{logic:'and',rules:[]},scheduled_at:'',parse_mode:'HTML',media_url:'',media_type:'image',stagger_seconds:0.05})
const editingId=ref(null)
const waMetaTemplates=ref([]),waTemplateError=ref(''),selectedMetaTemplateKey=ref(''),metaTemplateVars=ref({})
const mediaSource=ref('library'),selectedMediaId=ref(''),selectedSegmentId=ref(''),segmentName=ref(''),savingSegment=ref(false),segmentChanged=ref(false),segmentMissing=ref(false),selectedTemplateId=ref(''),templateName=ref(''),savingTemplate=ref(false)
const audiencePreview=ref({count:0,contacts:[]}),previewingAudience=ref(false),previewTimer=ref(null)
const filterOperators=[['equals','Equals'],['not_equals','Does not equal'],['contains','Contains'],['not_contains','Does not contain'],['starts_with','Starts with'],['ends_with','Ends with'],['is_empty','Is empty'],['is_not_empty','Is not empty']]
const composerOpen=ref(false)
const reportOpen=ref(false),report=ref(null),reportSearch=ref(''),reportStatus=ref('all'),reportSort=ref({key:'display_name',dir:'asc'}),reportPage=ref(1),reportPageSize=ref(25)
const validationOpen=ref(false),validationReport=ref(null),validationSearch=ref(''),validationStatus=ref('all')
const showEmoji=ref(false)
const emojis=['😀','😃','😄','😁','😊','🙂','😉','😍','🥰','😘','😂','🤣','😅','😎','🤩','🥳','🤔','👍','👎','👏','🙌','🙏','💪','👌','✅','❌','⚠️','❤️','💚','💙','🔥','⭐','🎉','🎁','📣','📌','📅','⏰','💬','📞','📧','🔗','🚀','✨']
const selectedMetaTemplate=computed(()=>waMetaTemplates.value.find(t=>(t.name+'|'+t.language)===selectedMetaTemplateKey.value)||null)
const metaTemplateVariableSlots=computed(()=>{const out=[];for(const comp of selectedMetaTemplate.value?.components||[]){if(!['BODY','HEADER'].includes(comp.type)||!comp.text)continue;const nums=[...comp.text.matchAll(/\{\{(\d+)\}\}/g)].map(m=>Number(m[1]));for(const n of [...new Set(nums)])out.push({key:comp.type.toLowerCase()+':'+n,label:comp.type+' variable {{'+n+'}}',component:comp.type.toLowerCase(),index:n})}return out})
const recipientCount=computed(()=>form.value.audience_type==='all'?audience.value.length:form.value.audience_type==='filtered'?audiencePreview.value.count:form.value.contact_ids.length)
const activeBots=computed(()=>(bots.value||[]).filter(b=>b.active))
const activeWhatsApp=computed(()=>(whatsappConnections.value||[]).filter(x=>x.active))
const activeAccounts=computed(()=>isTelegram.value?activeBots.value:activeWhatsApp.value)
const systemFieldKeys=['name','first_name','last_name','username','subscriber_id','language_code','phone','wa_id']
const systemFields=computed(()=>fields.value.filter(f=>systemFieldKeys.includes(f.key)))
const customFields=computed(()=>fields.value.filter(f=>!systemFieldKeys.includes(f.key)))
const zeroFilteredAudience=computed(()=>form.value.audience_type==='filtered'&&!previewingAudience.value&&audiencePreview.value.count===0)
const reportStatuses=computed(()=>[...new Set((report.value?.recipients||[]).map(r=>r.status))].sort())
const filteredReport=computed(()=>{let rows=[...(report.value?.recipients||[])];const q=reportSearch.value.trim().toLowerCase();if(q)rows=rows.filter(r=>[r.display_name,r.destination,r.status,r.provider_message_id,r.last_error].some(v=>String(v||'').toLowerCase().includes(q)));if(reportStatus.value!=='all')rows=rows.filter(r=>r.status===reportStatus.value);const {key,dir}=reportSort.value;rows.sort((a,b)=>String(a[key]??'').localeCompare(String(b[key]??''),undefined,{numeric:true})*(dir==='asc'?1:-1));return rows})
const reportPages=computed(()=>Math.max(1,Math.ceil(filteredReport.value.length/reportPageSize.value)))
const pagedReport=computed(()=>filteredReport.value.slice((reportPage.value-1)*reportPageSize.value,reportPage.value*reportPageSize.value))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function fmtSeconds(v){return v?new Intl.DateTimeFormat(undefined,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(v)):'—'}
function operatorLabel(op){return Object.fromEntries(filterOperators)[op]||op}
function fieldLabel(key){return fields.value.find(f=>f.key===key)?.label||key.replaceAll('_',' ')}
function providerTemplateData(b){return b?.provider_template||null}
function providerTemplateName(b){return providerTemplateData(b)?.name||'Meta template'}
function providerTemplateLanguage(b){return providerTemplateData(b)?.language||'—'}
function providerTemplateMappings(b){const t=providerTemplateData(b),out=[];for(const comp of (t?.components_payload||[])){let n=0;for(const p of (comp.parameters||[])){if(p.type==='text'){n++;out.push({slot:(comp.type||'body').toUpperCase()+' {{'+n+'}}',value:p.text||'—'})}}}return out}
function providerTemplatePreview(b){const t=providerTemplateData(b);if(!t)return b?.message_text||'';let body=b?.message_text||'';const ps=(t.components_payload||[]).find(x=>x.type==='body')?.parameters||[];ps.forEach((p,i)=>{body=body.replaceAll('{{'+(i+1)+'}}',p.text||'—')});return body}
function audienceDescription(b){if(b?.audience_type==='all')return isTelegram.value?'All subscribers':'All eligible contacts';if(b?.audience_type==='selected')return isTelegram.value?'Selected subscribers':'Selected eligible contacts';const spec=b?.audience_filter;if(!spec?.rules?.length)return 'Filtered audience';const joiner=spec.logic==='or'?' OR ':' AND ';return 'Filtered audience — Match '+(spec.logic==='or'?'ANY':'ALL')+': '+spec.rules.map(r=>fieldLabel(r.field)+' '+operatorLabel(r.operator).toLowerCase()+(operatorNeedsValue(r.operator)?' “'+r.value+'”':'')).join(joiner)}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function highlightTemplateTokens(s){return escapeHtml(s).replace(/%[a-zA-Z0-9_.-]+%/g,t=>'<span class="template-variable-chip">'+t+'</span>').replace(/\n/g,'<br>')}
function deliverySpeed(v){const n=Number(v||0);if(n<=0.051)return 'Normal (~20 messages/sec)';if(n<=0.51)return 'Staggered (~2 messages/sec)';if(n===1)return '1 message every second';return '1 message every '+n+' seconds'}
async function load(){loading.value=true;error.value='';try{if(isTelegram.value)bots.value=await api.telegramBots();else whatsappConnections.value=await api.whatsappConnections();if(!form.value.channel_account_id&&activeAccounts.value.length)form.value.channel_account_id=activeAccounts.value[0].id;await Promise.all([loadHistory(),loadAudience(),loadFields(),loadMediaAssets(),loadMetaTemplates()])}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadHistory(){broadcasts.value=form.value.channel_account_id?await api.broadcasts(props.channel,Number(form.value.channel_account_id)):[];if(selected.value){const row=broadcasts.value.find(b=>b.id===selected.value.id);if(row){try{selected.value=await api.broadcast(row.id)}catch(e){if(e?.status===404)selected.value=null;else throw e}}else selected.value=null}}
async function loadMetaTemplates(){waMetaTemplates.value=[];waTemplateError.value='';if(isTelegram.value||!form.value.channel_account_id)return;try{waMetaTemplates.value=await api.broadcastWhatsAppTemplates(Number(form.value.channel_account_id))}catch(e){waTemplateError.value=e.message||'Could not load approved WhatsApp templates'}}
function buildMetaProviderTemplate(){const tpl=selectedMetaTemplate.value;if(!tpl)return null;const grouped={};for(const slot of metaTemplateVariableSlots.value){const value=metaTemplateVars.value[slot.key]||'';(grouped[slot.component]??=[])[slot.index-1]={type:'text',text:value}}const components_payload=Object.entries(grouped).map(([type,parameters])=>({type,parameters}));return {id:tpl.id,name:tpl.name,language:tpl.language,category:tpl.category,components:tpl.components,components_payload}}
function selectMetaTemplate(){metaTemplateVars.value={};const tpl=selectedMetaTemplate.value;if(!tpl){form.value.provider_template=null;form.value.message_text='';return}form.value.message_text=(tpl.components||[]).filter(x=>x.type==='BODY').map(x=>x.text||'').join('\n');form.value.provider_template=buildMetaProviderTemplate()}
async function messageModeChanged(){form.value.contact_ids=[];audiencePreview.value={count:0,contacts:[]};if(form.value.message_mode==='template')await loadMetaTemplates();else{selectedMetaTemplateKey.value='';metaTemplateVars.value={};form.value.provider_template=null}await loadAudience();if(form.value.audience_type==='filtered')await previewAudience()}
async function loadFields(){fields.value=form.value.channel_account_id?(isTelegram.value?await api.broadcastTelegramFields(Number(form.value.channel_account_id)):await api.broadcastWhatsAppFields(Number(form.value.channel_account_id))):[]}
async function loadSegments(){try{segments.value=await api.audienceSegments(props.channel)}catch(e){error.value=e.message}}
async function loadTemplates(){try{templates.value=await api.broadcastTemplates(props.channel)}catch(e){error.value=e.message}}
function templatePayload(name){return {name,channel:props.channel,message_text:form.value.message_text,parse_mode:form.value.parse_mode||'HTML',media_url:form.value.media_url||null,media_type:form.value.media_url?form.value.media_type:null,stagger_seconds:Number(form.value.stagger_seconds||0.05)}}
function syncTemplateMedia(){const asset=mediaAssets.value.find(a=>a.url===form.value.media_url);mediaSource.value=asset?'library':(form.value.media_url?'external':'library');selectedMediaId.value=asset?.id||''}
function loadSavedTemplate(){const t=templates.value.find(x=>String(x.id)===String(selectedTemplateId.value));if(!t){templateName.value='';return}templateName.value=t.name;form.value.message_text=t.message_text;form.value.parse_mode=t.parse_mode||'HTML';form.value.media_url=t.media_url||'';form.value.media_type=t.media_type||'image';form.value.stagger_seconds=Number(t.stagger_seconds||0.05);syncTemplateMedia();success.value='Template “'+t.name+'” loaded.'}
async function saveTemplate(){const name=templateName.value.trim();if(!name){error.value='Enter a template name before saving.';return}if(!form.value.message_text.trim()){error.value='Enter a message before saving a template.';return}savingTemplate.value=true;error.value='';try{const saved=await api.createBroadcastTemplate(templatePayload(name));await loadTemplates();selectedTemplateId.value=saved.id;templateName.value=saved.name;success.value='Broadcast template “'+saved.name+'” saved.'}catch(e){error.value=e.message}finally{savingTemplate.value=false}}
async function updateTemplate(){const t=templates.value.find(x=>String(x.id)===String(selectedTemplateId.value));if(!t)return;const name=templateName.value.trim();if(!name){error.value='Enter a template name.';return}savingTemplate.value=true;error.value='';try{await api.updateBroadcastTemplate(t.id,templatePayload(name));await loadTemplates();success.value='Broadcast template “'+name+'” updated.'}catch(e){error.value=e.message}finally{savingTemplate.value=false}}
async function deleteTemplate(){const t=templates.value.find(x=>String(x.id)===String(selectedTemplateId.value));if(!t||!confirm('Delete broadcast template “'+t.name+'”? Existing broadcasts will not be changed.'))return;error.value='';try{await api.deleteBroadcastTemplate(t.id);selectedTemplateId.value='';templateName.value='';await loadTemplates();success.value='Broadcast template deleted.'}catch(e){error.value=e.message}}
function cloneFilter(spec){return JSON.parse(JSON.stringify(spec||{logic:'and',rules:[]}))}
function sameFilter(a,b){return JSON.stringify(cloneFilter(a))===JSON.stringify(cloneFilter(b))}
function restoreSegmentProvenance(source){segmentChanged.value=false;segmentMissing.value=false;selectedSegmentId.value='';segmentName.value='';if(!source?.audience_segment_id)return;const segment=segments.value.find(s=>Number(s.id)===Number(source.audience_segment_id));if(!segment){segmentMissing.value=true;return}selectedSegmentId.value=segment.id;segmentName.value=segment.name;segmentChanged.value=!sameFilter(segment.audience_filter,source.audience_filter)}
async function reloadSegmentRules(){const segment=segments.value.find(s=>String(s.id)===String(selectedSegmentId.value));if(!segment)return;form.value.audience_filter=cloneFilter(segment.audience_filter);segmentChanged.value=false;await previewAudience()}
async function loadSavedSegment(){segmentChanged.value=false;segmentMissing.value=false;const segment=segments.value.find(s=>String(s.id)===String(selectedSegmentId.value));if(!segment){segmentName.value='';return}segmentName.value=segment.name;form.value.audience_filter=cloneFilter(segment.audience_filter);await previewAudience()}
async function saveSegment(){const name=segmentName.value.trim();if(!name){error.value='Enter a segment name before saving.';return}if(!form.value.audience_filter.rules.length){error.value='Add at least one audience rule before saving a segment.';return}savingSegment.value=true;error.value='';try{const saved=await api.createAudienceSegment({name,channel:props.channel,audience_filter:cloneFilter(form.value.audience_filter)});await loadSegments();selectedSegmentId.value=saved.id;segmentName.value=saved.name;success.value='Audience segment “'+saved.name+'” saved.'}catch(e){error.value=e.message}finally{savingSegment.value=false}}
async function updateSegment(){const segment=segments.value.find(s=>String(s.id)===String(selectedSegmentId.value));if(!segment)return;const name=segmentName.value.trim();if(!name){error.value='Enter a segment name.';return}savingSegment.value=true;error.value='';try{await api.updateAudienceSegment(segment.id,{name,channel:props.channel,audience_filter:cloneFilter(form.value.audience_filter)});await loadSegments();success.value='Audience segment “'+name+'” updated.'}catch(e){error.value=e.message}finally{savingSegment.value=false}}
async function deleteSegment(){const segment=segments.value.find(s=>String(s.id)===String(selectedSegmentId.value));if(!segment||!confirm('Delete saved segment “'+segment.name+'”? Existing broadcasts will not be changed.'))return;error.value='';try{await api.deleteAudienceSegment(segment.id);selectedSegmentId.value='';segmentName.value='';await loadSegments();success.value='Saved audience segment deleted.'}catch(e){error.value=e.message}}
async function loadAudience(){audience.value=[];form.value.contact_ids=[];if(!form.value.channel_account_id)return;try{audience.value=isTelegram.value?await api.broadcastTelegramAudience(Number(form.value.channel_account_id)):await api.broadcastWhatsAppAudience(Number(form.value.channel_account_id),form.value.message_mode)}catch(e){error.value=e.message}}
function addAudienceRule(){form.value.audience_filter.rules.push({field:fields.value[0]?.key||'first_name',operator:'equals',value:''});scheduleAudiencePreview()}
function removeAudienceRule(index){form.value.audience_filter.rules.splice(index,1);scheduleAudiencePreview()}
function operatorNeedsValue(op){return !['is_empty','is_not_empty'].includes(op)}
function scheduleAudiencePreview(){if(form.value.audience_type!=='filtered')return;clearTimeout(previewTimer.value);previewTimer.value=setTimeout(previewAudience,250)}
async function previewAudience(){if(form.value.audience_type!=='filtered'||!form.value.channel_account_id){audiencePreview.value={count:0,contacts:[]};return}previewingAudience.value=true;try{audiencePreview.value=isTelegram.value?await api.broadcastTelegramAudiencePreview(Number(form.value.channel_account_id),form.value.audience_filter):await api.broadcastWhatsAppAudiencePreview(Number(form.value.channel_account_id),form.value.audience_filter,form.value.message_mode)}catch(e){error.value=e.message}finally{previewingAudience.value=false}}
function audienceTypeChanged(){if(form.value.audience_type==='filtered'){if(!form.value.audience_filter.rules.length)addAudienceRule();else previewAudience()}}
async function loadMediaAssets(){mediaAssets.value=[];if(!form.value.channel_account_id||!isTelegram.value){if(!isTelegram.value&&form.value.media_url)mediaSource.value='external';return}try{mediaAssets.value=await api.mediaAssets(Number(form.value.channel_account_id));const match=mediaAssets.value.find(a=>a.url===form.value.media_url);if(match){selectedMediaId.value=match.id;mediaSource.value='library'}}catch(e){error.value=e.message}}
function chooseMedia(){const a=mediaAssets.value.find(x=>String(x.id)===String(selectedMediaId.value));if(!a){form.value.media_url='';return}form.value.media_url=a.url;form.value.media_type=a.media_type}
function setMediaSource(source){mediaSource.value=source;selectedMediaId.value='';form.value.media_url=''}
async function uploadMedia(event){const file=event.target.files?.[0];event.target.value='';if(!file||!form.value.channel_account_id)return;uploadingMedia.value=true;error.value='';try{const a=await api.uploadMediaAsset(Number(form.value.channel_account_id),file);await loadMediaAssets();selectedMediaId.value=a.id;form.value.media_url=a.url;form.value.media_type=a.media_type;mediaSource.value='library';success.value='Media uploaded to the library.'}catch(e){error.value=e.message}finally{uploadingMedia.value=false}}
function mediaPreviewUrl(url){if(!url)return '';if(/^https?:\/\//i.test(url))return url;return url.startsWith('/')?url:'/'+url}
function localDateTime(v){if(!v)return '';const d=new Date(v),pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())}
function resetForm(){editingId.value=null;selectedMetaTemplateKey.value='';metaTemplateVars.value={};mediaSource.value=isTelegram.value?'library':'external';selectedMediaId.value='';selectedSegmentId.value='';segmentName.value='';segmentChanged.value=false;segmentMissing.value=false;selectedTemplateId.value='';templateName.value='';form.value={name:'',channel_account_id:activeAccounts.value[0]?.id||'',message_text:'',message_mode:'freeform',provider_template:null,audience_type:'all',contact_ids:[],audience_filter:{logic:'and',rules:[]},scheduled_at:'',parse_mode:'HTML',media_url:'',media_type:'image',stagger_seconds:0.05};loadAudience()}
function newBroadcast(){resetForm();composerOpen.value=true}
async function duplicateBroadcast(row){error.value='';success.value='';try{const source=selected.value?.id===row.id?selected.value:await api.broadcast(row.id);editingId.value=null;form.value.name=(source.name+' Copy').slice(0,150);form.value.channel_account_id=source.channel_account_id;form.value.message_text=source.message_text;form.value.parse_mode=source.parse_mode||'HTML';form.value.media_url=source.media_url||'';form.value.media_type=source.media_type||'image';form.value.stagger_seconds=source.stagger_seconds||0.05;form.value.audience_type=source.audience_type;form.value.audience_filter=source.audience_filter||{logic:'and',rules:[]};form.value.scheduled_at='';await Promise.all([loadAudience(),loadFields(),loadMediaAssets()]);mediaSource.value=mediaAssets.value.some(a=>a.url===source.media_url)?'library':'external';selectedMediaId.value=mediaAssets.value.find(a=>a.url===source.media_url)?.id||'';if(source.audience_type==='selected')form.value.contact_ids=(source.recipients||[]).map(r=>r.contact_id);if(source.audience_type==='filtered'){restoreSegmentProvenance(source);await previewAudience()}composerOpen.value=true;success.value='Broadcast copied into a new draft. Review it and click Create draft when ready.'}catch(e){error.value=e.message}}
function closeComposer(){composerOpen.value=false;showEmoji.value=false;resetForm()}
async function editBroadcast(){if(!selected.value||selected.value.status!=='draft')return;editingId.value=selected.value.id;form.value.name=selected.value.name;form.value.channel_account_id=selected.value.channel_account_id;form.value.message_text=selected.value.message_text;form.value.message_mode=selected.value.message_mode||'freeform';form.value.provider_template=selected.value.provider_template||null;if(form.value.provider_template){selectedMetaTemplateKey.value=form.value.provider_template.name+'|'+form.value.provider_template.language;for(const comp of form.value.provider_template.components_payload||[])for(let i=0;i<(comp.parameters||[]).length;i++)metaTemplateVars.value[comp.type+':'+(i+1)]=comp.parameters[i]?.text||''}form.value.parse_mode=selected.value.parse_mode||'HTML';form.value.media_url=selected.value.media_url||'';form.value.media_type=selected.value.media_type||'image';form.value.stagger_seconds=selected.value.stagger_seconds||0.05;form.value.audience_type=selected.value.audience_type;form.value.audience_filter=selected.value.audience_filter||{logic:'and',rules:[]};form.value.scheduled_at=localDateTime(selected.value.scheduled_at);await Promise.all([loadAudience(),loadMediaAssets()]);mediaSource.value=mediaAssets.value.some(a=>a.url===selected.value.media_url)?'library':'external';selectedMediaId.value=mediaAssets.value.find(a=>a.url===selected.value.media_url)?.id||'';if(form.value.audience_type==='selected')form.value.contact_ids=selected.value.recipients.map(r=>r.contact_id);if(form.value.audience_type==='filtered'){restoreSegmentProvenance(selected.value);await previewAudience()}composerOpen.value=true}
async function deleteBroadcast(){if(!selected.value||selected.value.status!=='draft'||!confirm('Delete this draft broadcast? This cannot be undone.'))return;error.value='';try{await api.deleteBroadcast(selected.value.id);selected.value=null;editingId.value=null;composerOpen.value=false;resetForm();await loadHistory();success.value='Draft broadcast deleted.'}catch(e){error.value=e.message}}
function insertEmoji(e){insertText(e);showEmoji.value=false}
function insertText(token){const el=document.querySelector('.broadcast-message');if(!el){form.value.message_text+=token;return}const start=el.selectionStart??form.value.message_text.length,end=el.selectionEnd??start;form.value.message_text=form.value.message_text.slice(0,start)+token+form.value.message_text.slice(end);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(start+token.length,start+token.length)})}
function insertField(key){const el=document.querySelector('.broadcast-message');const token='%'+key+'%';if(!el){form.value.message_text+=token;return}const start=el.selectionStart??form.value.message_text.length,end=el.selectionEnd??start;form.value.message_text=form.value.message_text.slice(0,start)+token+form.value.message_text.slice(end);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(start+token.length,start+token.length)})}
function wrap(open,close=open){const el=document.querySelector('.broadcast-message');if(!el)return;const s=el.selectionStart,e=el.selectionEnd,t=form.value.message_text;form.value.message_text=t.slice(0,s)+open+t.slice(s,e)+close+t.slice(e);requestAnimationFrame(()=>el.focus())}
function toggleAll(){form.value.contact_ids=form.value.contact_ids.length===audience.value.length?[]:audience.value.map(x=>x.id)}
async function createBroadcast(){if(saving.value)return;saving.value=true;error.value='';success.value='';try{if(!isTelegram.value&&form.value.message_mode==='template')form.value.provider_template=buildMetaProviderTemplate();const payload={...form.value,audience_segment_id:form.value.audience_type==='filtered'&&selectedSegmentId.value?Number(selectedSegmentId.value):null,channel:props.channel,channel_account_id:Number(form.value.channel_account_id),scheduled_at:form.value.scheduled_at?new Date(form.value.scheduled_at).toISOString():null};const saved=editingId.value?await api.updateBroadcast(editingId.value,payload):await api.createBroadcast(payload);selected.value=await api.broadcast(saved.id);broadcasts.value=await api.broadcasts(props.channel,Number(form.value.channel_account_id));success.value=editingId.value?'Draft broadcast updated.':'Draft created with '+saved.total_recipients+' recipient'+(saved.total_recipients===1?'':'s')+'.';editingId.value=null;composerOpen.value=false;resetForm()}catch(e){error.value=e.message}finally{saving.value=false}}
async function openBroadcast(row){error.value='';if(selected.value?.id===row.id){selected.value=null;return}try{selected.value=await api.broadcast(row.id)}catch(e){error.value=e.message}}
async function openStats(row){error.value='';try{report.value=await api.broadcast(row.id);reportSearch.value='';reportStatus.value='all';reportPage.value=1;reportOpen.value=true}catch(e){error.value=e.message}}
function closeStats(){reportOpen.value=false;report.value=null}
async function openValidation(row){error.value='';try{validationReport.value=await api.broadcast(row.id);validationSearch.value='';validationStatus.value='all';validationOpen.value=true}catch(e){error.value=e.message}}
function closeValidation(){validationOpen.value=false;validationReport.value=null}
const validationRows=computed(()=>{let rows=[...(validationReport.value?.audience_validation||[])];const q=validationSearch.value.trim().toLowerCase();if(q)rows=rows.filter(r=>[r.display_name,r.destination,r.status,...(r.reasons||[]).map(x=>x.message)].some(v=>String(v||'').toLowerCase().includes(q)));if(validationStatus.value!=='all')rows=rows.filter(r=>r.status===validationStatus.value);return rows})
const validationReady=computed(()=>validationReport.value?.audience_validation?.filter(x=>x.status==='ready').length||0)
const validationExcluded=computed(()=>validationReport.value?.audience_validation?.filter(x=>x.status==='excluded').length||0)
function validationReason(r){return (r.reasons||[]).map(x=>x.message).join('; ')||'Ready to send'}
function validationExportRows(){return validationRows.value.map(r=>({Recipient:r.display_name||'',Destination:r.destination||'',Status:r.status||'',Reason:validationReason(r)}))}
function validationFilename(ext){return 'broadcast-'+(validationReport.value?.id||'validation')+'-audience-validation.'+ext}
function exportValidationCsv(){const rows=validationExportRows(),headers=['Recipient','Destination','Status','Reason'],esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';downloadBlob(new Blob([[headers.map(esc).join(','),...rows.map(r=>headers.map(h=>esc(r[h])).join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'}),validationFilename('csv'))}
function exportValidationExcel(){const ws=XLSX.utils.json_to_sheet(validationExportRows());const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Audience validation');XLSX.writeFile(wb,validationFilename('xlsx'))}
function exportValidationPdf(){const doc=new jsPDF({orientation:'landscape'});doc.setFontSize(16);doc.text((validationReport.value?.name||'Broadcast')+' — Audience validation',14,14);doc.setFontSize(9);doc.text('Evaluated: '+(validationReport.value?.audience_evaluated_count||0)+'   Ready: '+validationReady.value+'   Excluded: '+validationExcluded.value,14,21);autoTable(doc,{startY:27,head:[['Recipient','Destination','Status','Reason']],body:validationExportRows().map(r=>[r.Recipient,r.Destination,r.Status,r.Reason]),styles:{fontSize:8}});doc.save(validationFilename('pdf'))}
function sortReport(key){reportSort.value={key,dir:reportSort.value.key===key&&reportSort.value.dir==='asc'?'desc':'asc'};reportPage.value=1}
function reportRows(){return filteredReport.value.map(r=>({Recipient:r.display_name||'',Destination:r.destination||'',Status:r.status||'',Attempts:r.attempts??0,'Provider Message ID':r.provider_message_id||'','Sent At':r.sent_at?fmt(r.sent_at):'','Failure Reason':r.last_error||''}))}
function reportFilename(ext){return 'broadcast-'+(report.value?.id||'report')+'-'+String(report.value?.name||'report').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()+'.'+ext}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCsv(){const rows=reportRows(),headers=Object.keys(rows[0]||{Recipient:'',Destination:'',Status:'',Attempts:'','Provider Message ID':'','Sent At':'','Failure Reason':''});const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';downloadBlob(new Blob([[headers.map(esc).join(','),...rows.map(r=>headers.map(h=>esc(r[h])).join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'}),reportFilename('csv'))}
function exportExcel(){const ws=XLSX.utils.json_to_sheet(reportRows());const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Recipients');XLSX.writeFile(wb,reportFilename('xlsx'))}
function exportPdf(){const doc=new jsPDF({orientation:'landscape'});doc.setFontSize(16);doc.text(report.value?.name||'Broadcast report',14,14);doc.setFontSize(9);doc.text('Status: '+(report.value?.status||'')+'   Recipients: '+(report.value?.total_recipients||0)+'   Sent: '+(report.value?.sent_count||0)+'   Failed: '+(report.value?.failed_count||0),14,21);const rows=reportRows();const heads=Object.keys(rows[0]||{Recipient:'',Destination:'',Status:'',Attempts:'','Provider Message ID':'','Sent At':'','Failure Reason':''});autoTable(doc,{startY:27,head:[heads],body:rows.map(r=>heads.map(h=>r[h])),styles:{fontSize:7}});doc.save(reportFilename('pdf'))}
async function actOn(row,action){if(selected.value?.id!==row.id)selected.value=await api.broadcast(row.id);return action()}
async function queue(){if(!selected.value)return;error.value='';try{selected.value=await api.queueBroadcast(selected.value.id);broadcasts.value=await api.broadcasts(props.channel,Number(form.value.channel_account_id));success.value=selected.value.status==='scheduled'?'Broadcast scheduled.':'Broadcast queued for delivery.'}catch(e){error.value=e.message}}
async function pause(){if(!selected.value)return;error.value='';try{selected.value=await api.pauseBroadcast(selected.value.id);await loadHistory();success.value='Broadcast paused. Pending recipients will not be sent until you resume it.'}catch(e){error.value=e.message}}
async function resume(){if(!selected.value)return;error.value='';try{selected.value=await api.resumeBroadcast(selected.value.id);await loadHistory();success.value='Broadcast resumed and queued for delivery.'}catch(e){error.value=e.message}}
async function cancel(){if(!selected.value||!confirm('Cancel this broadcast? Recipients already sent will remain sent, but pending recipients will not be delivered.'))return;error.value='';try{selected.value=await api.cancelBroadcast(selected.value.id);await loadHistory();success.value='Broadcast cancelled.'}catch(e){error.value=e.message}}
async function sendTest(r){error.value='';success.value='';try{await api.testBroadcast(selected.value.id,r.contact_id);success.value='Test message sent to '+(r.display_name||r.destination)+'.'}catch(e){error.value=e.message}}
async function reloadChannel(){selected.value=null;broadcasts.value=[];form.value.channel_account_id='';await Promise.all([load(),loadSegments(),loadTemplates()])}
watch(()=>props.channel,reloadChannel)
onMounted(async()=>{await Promise.all([load(),loadSegments(),loadTemplates()])})
</script>
<template>
<section class="broadcast-page">
<header class="broadcast-head"><div><p class="eyebrow">Messaging</p><h1>Broadcasts</h1><p>Send {{channelLabel}} messages to your existing audience.</p></div><div class="head-actions"><button class="primary" @click="newBroadcast">+ New Broadcast Message</button><button class="secondary" @click="load">↻ Refresh</button></div></header>
<p v-if="error" class="broadcast-error">{{error}}</p><p v-if="success" class="broadcast-success">{{success}}</p>

<section class="broadcast-card list-card"><div class="list-title"><h2>Broadcast history</h2><span>{{broadcasts.length}} broadcast{{broadcasts.length===1?'':'s'}}</span></div>
<div v-if="loading">Loading…</div><div v-else-if="!broadcasts.length" class="empty">No broadcasts yet. Create your first broadcast message.</div>
<template v-for="b in broadcasts" :key="b.id">
<div class="broadcast-row" :class="{active:selected?.id===b.id}" @click="openBroadcast(b)">
  <span class="row-main"><strong>{{b.name}}</strong><small>{{fmt(b.created_at)}} · {{channelLabel}}</small></span>
  <span class="row-metric"><strong>{{b.total_recipients}}</strong><small>Recipients</small></span>
  <span class="row-metric"><strong>{{b.sent_count}}</strong><small>Sent</small></span>
  <span class="row-metric"><strong>{{b.failed_count}}</strong><small>Failed</small></span>
  <span class="row-status"><b class="status">{{b.status}}</b><small v-if="b.scheduled_at">{{fmt(b.scheduled_at)}}</small></span>
  <span class="row-actions" @click.stop>
    <button class="small-btn" @click="duplicateBroadcast(b)">Duplicate</button>
    <button v-if="b.status==='draft'" class="small-btn" @click="actOn(b,editBroadcast)">Edit</button>
    <button v-if="b.status==='draft'" class="small-btn primary" @click="actOn(b,queue)">{{b.scheduled_at?'Schedule':'Send now'}}</button>
    <button v-if="b.status==='draft'" class="small-btn danger" @click="actOn(b,deleteBroadcast)">Delete</button>
    <button v-if="['queued','scheduled','sending'].includes(b.status)" class="small-btn" @click="actOn(b,pause)">Pause</button>
    <button v-if="b.status==='paused' && (b.sent_count+b.failed_count)<b.total_recipients" class="small-btn primary" @click="actOn(b,resume)">Resume</button>
    <button v-if="['queued','scheduled','sending','paused'].includes(b.status) && (b.sent_count+b.failed_count)<b.total_recipients" class="small-btn danger" @click="actOn(b,cancel)">Cancel</button>
    <button v-if="b.audience_evaluated_count!=null" class="small-btn" @click="openValidation(b)">Validation<span v-if="b.audience_evaluated_count>b.total_recipients"> ({{b.audience_evaluated_count-b.total_recipients}})</span></button>
    <button class="small-btn" @click="openStats(b)">Stats</button>
  </span>
  <span class="chevron">{{selected?.id===b.id?'⌃':'⌄'}}</span>
</div>
<div v-if="selected?.id===b.id" class="row-detail">
  <div class="metrics"><div><strong>{{selected.total_recipients}}</strong><span>Recipients</span></div><div><strong>{{selected.sent_count}}</strong><span>Sent</span></div><div><strong>{{selected.failed_count}}</strong><span>Failed</span></div></div>
  <div class="detail-columns"><div><h3>Message</h3><div v-if="selected.channel==='whatsapp'&&selected.message_mode==='template'&&selected.provider_template" class="history-template-summary"><div class="history-template-head"><span><small>Meta template</small><strong>{{providerTemplateName(selected)}}</strong></span><span><small>Language</small><strong>{{providerTemplateLanguage(selected)}}</strong></span></div><div v-if="providerTemplateMappings(selected).length" class="history-template-mappings"><small>Parameter mappings</small><div v-for="m in providerTemplateMappings(selected)" :key="m.slot"><code>{{m.slot}}</code><span>→</span><strong>{{m.value}}</strong></div></div><small class="history-template-preview-label">Template preview</small><div class="message-preview template-token-preview" v-html="highlightTemplateTokens(providerTemplatePreview(selected))"></div></div><pre v-else class="message-preview">{{selected.message_text}}</pre><div v-if="selected.media_url" class="history-media"><img v-if="selected.media_type==='image'" :src="mediaPreviewUrl(selected.media_url)" alt="Broadcast media preview"/><video v-else-if="selected.media_type==='video'" :src="mediaPreviewUrl(selected.media_url)" controls preload="metadata"></video><a v-else class="history-file" :href="mediaPreviewUrl(selected.media_url)" target="_blank" rel="noopener">📎 <span><strong>Attached file</strong><small>Open attachment</small></span></a><div class="history-media-meta"><strong>{{selected.media_type||'Media'}}</strong><a :href="mediaPreviewUrl(selected.media_url)" target="_blank" rel="noopener">Open media ↗</a></div></div><p><strong>Audience:</strong> {{audienceDescription(selected)}}</p><p><strong>Delivery speed:</strong> {{deliverySpeed(selected.stagger_seconds)}}</p><p v-if="selected.scheduled_at"><strong>Scheduled:</strong> {{fmt(selected.scheduled_at)}}</p></div>
  <div class="recipient-list"><h3>Recipients</h3><article v-for="r in selected.recipients" :key="r.id"><span><strong>{{r.display_name||r.destination}}</strong><small>{{r.destination}}</small></span><span><b class="status">{{r.status}}</b><button v-if="selected.status==='draft'" class="link-btn" @click="sendTest(r)">Send test</button></span><p v-if="r.last_error">{{r.last_error}}</p></article></div></div>
</div>
</template></section>

<div v-if="validationOpen&&validationReport" class="modal-backdrop" @click.self="closeValidation">
<section class="broadcast-card report-modal">
<div class="composer-title"><div><p class="eyebrow">Audience validation #{{validationReport.id}}</p><h2>{{validationReport.name}}</h2><p>{{channelLabel}} · Audience snapshot taken when this draft was saved</p></div><button type="button" class="modal-close" @click="closeValidation">×</button></div>
<div class="metrics validation-metrics"><div><strong>{{validationReport.audience_evaluated_count||0}}</strong><span>Evaluated</span></div><div><strong>{{validationReady}}</strong><span>Ready</span></div><div><strong>{{validationExcluded}}</strong><span>Excluded</span></div></div>
<div class="report-toolbar"><input v-model="validationSearch" placeholder="Search recipient, ID or reason…"/><select v-model="validationStatus"><option value="all">All results</option><option value="ready">Ready</option><option value="excluded">Excluded</option></select><span class="toolbar-spacer"></span><button class="secondary" @click="exportValidationCsv">CSV</button><button class="secondary" @click="exportValidationExcel">Excel</button><button class="secondary" @click="exportValidationPdf">PDF</button></div>
<div class="report-table-wrap"><table class="report-table"><thead><tr><th>Recipient</th><th>{{isTelegram?'Telegram ID':'WhatsApp ID'}}</th><th>Status</th><th>Validation result</th></tr></thead><tbody><tr v-for="(r,i) in validationRows" :key="r.contact_id+'-'+i"><td><strong>{{r.display_name||'—'}}</strong></td><td>{{r.destination||'—'}}</td><td><b class="status" :class="{validationExcluded:r.status==='excluded'}">{{r.status}}</b></td><td class="validation-reason"><span v-for="reason in r.reasons||[]" :key="reason.code+(reason.field||'')">{{reason.message}}</span><span v-if="!r.reasons?.length">Ready to send</span></td></tr><tr v-if="!validationRows.length"><td colspan="4" class="empty">No validation results match the current filters.</td></tr></tbody></table></div>
<div class="validation-note">Only contacts marked <strong>Ready</strong> are snapshotted as broadcast recipients. Excluded contacts are retained in this validation report for auditing.</div>
</section></div>

<div v-if="reportOpen&&report" class="modal-backdrop" @click.self="closeStats">
<section class="broadcast-card report-modal">
<div class="composer-title"><div><p class="eyebrow">Broadcast report #{{report.id}}</p><h2>{{report.name}}</h2><p>{{fmt(report.created_at)}} · {{channelLabel}} · <b class="status">{{report.status}}</b> · {{deliverySpeed(report.stagger_seconds)}}</p></div><button type="button" class="modal-close" @click="closeStats">×</button></div>
<div class="metrics"><div><strong>{{report.total_recipients}}</strong><span>Recipients</span></div><div><strong>{{report.sent_count}}</strong><span>Sent</span></div><div><strong>{{report.failed_count}}</strong><span>Failed</span></div></div>
<div class="report-toolbar"><input v-model="reportSearch" @input="reportPage=1" placeholder="Search recipient, ID, status or error…"/><select v-model="reportStatus" @change="reportPage=1"><option value="all">All statuses</option><option v-for="s in reportStatuses" :key="s" :value="s">{{s}}</option></select><span class="toolbar-spacer"></span><button class="secondary" @click="exportCsv">CSV</button><button class="secondary" @click="exportExcel">Excel</button><button class="secondary" @click="exportPdf">PDF</button></div>
<div class="report-table-wrap"><table class="report-table"><thead><tr><th @click="sortReport('display_name')">Recipient</th><th @click="sortReport('destination')">{{isTelegram?'Telegram ID':'WhatsApp ID'}}</th><th @click="sortReport('status')">Status</th><th @click="sortReport('attempts')">Attempts</th><th @click="sortReport('provider_message_id')">Message ID</th><th @click="sortReport('sent_at')">Sent</th><th @click="sortReport('last_error')">Failure reason</th></tr></thead><tbody><tr v-for="r in pagedReport" :key="r.id"><td><strong>{{r.display_name||'—'}}</strong></td><td>{{r.destination}}</td><td><b class="status">{{r.status}}</b></td><td>{{r.attempts}}</td><td>{{r.provider_message_id||'—'}}</td><td>{{fmtSeconds(r.sent_at)}}</td><td class="error-cell">{{r.last_error||'—'}}</td></tr><tr v-if="!pagedReport.length"><td colspan="7" class="empty">No recipients match the current filters.</td></tr></tbody></table></div>
<div class="report-footer"><span>Showing {{pagedReport.length}} of {{filteredReport.length}} recipient{{filteredReport.length===1?'':'s'}}</span><div><select v-model.number="reportPageSize" @change="reportPage=1"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select><button class="secondary" :disabled="reportPage<=1" @click="reportPage--">‹</button><span>Page {{reportPage}} / {{reportPages}}</span><button class="secondary" :disabled="reportPage>=reportPages" @click="reportPage++">›</button></div></div>
</section></div>

<div v-if="composerOpen" class="modal-backdrop" @click.self="closeComposer">
<form class="broadcast-card composer-modal" @submit.prevent="createBroadcast">
<div class="composer-title"><div><p class="eyebrow">{{editingId?'Edit draft':'New message'}}</p><h2>{{editingId?'Edit broadcast':'New Broadcast Message'}}</h2></div><button type="button" class="modal-close" @click="closeComposer">×</button></div>
<div class="composer-grid"><label>Name<input v-model="form.name" maxlength="150" required placeholder="September promotion"/></label><label>Channel<select disabled><option>{{channelLabel}}</option></select></label></div>
<label>{{isTelegram?'Telegram bot':'WhatsApp number'}}<select v-model="form.channel_account_id" required @change="loadHistory();loadAudience();loadFields();loadMediaAssets()"><option disabled value="">{{isTelegram?'Select bot…':'Select WhatsApp number…'}}</option><option v-for="account in activeAccounts" :key="account.id" :value="account.id">{{isTelegram?(account.first_name||account.username||('Bot '+account.id)):(account.verified_name||account.display_phone_number||('WhatsApp '+account.id))}}{{isTelegram&&account.username?' (@'+account.username+')':(!isTelegram&&account.display_phone_number?' · '+account.display_phone_number:'')}}</option></select></label>
<div v-if="!isTelegram" class="wa-mode"><label>Message type<select v-model="form.message_mode" @change="messageModeChanged"><option value="freeform">Free-form message</option><option value="template">Approved WhatsApp template</option></select></label><p class="wa-window-note" v-if="form.message_mode==='freeform'">Free-form broadcasts include only contacts whose customer service window is currently open.</p><p class="wa-template-note" v-else>Approved templates can start a conversation outside the customer service window. The selected template and parameters are snapshotted into this broadcast.</p></div><div v-if="!isTelegram&&form.message_mode==='template'" class="meta-template-panel"><div v-if="waTemplateError" class="wa-template-error"><strong>WhatsApp templates unavailable</strong><span>{{waTemplateError}}</span><button type="button" class="secondary" @click="loadMetaTemplates">Retry</button></div><label>Approved Meta template<select v-model="selectedMetaTemplateKey" @change="selectMetaTemplate"><option value="">Select approved template…</option><option v-for="tpl in waMetaTemplates" :key="tpl.id+'-'+tpl.language" :value="tpl.name+'|'+tpl.language">{{tpl.name}} · {{tpl.language}} · {{tpl.category}}</option></select></label><div v-if="selectedMetaTemplate" class="meta-template-preview"><strong>Template preview</strong><div v-for="comp in selectedMetaTemplate.components" :key="comp.type"><small>{{comp.type}}</small><p v-if="comp.text">{{comp.text}}</p></div></div><div v-if="metaTemplateVariableSlots.length" class="template-vars"><label v-for="slot in metaTemplateVariableSlots" :key="slot.key">{{slot.label}}<div class="template-var-row"><input v-model="metaTemplateVars[slot.key]" placeholder="Text or %field%"/><select @change="if($event.target.value){metaTemplateVars[slot.key]='%'+$event.target.value+'%';$event.target.value=''}"><option value="">Insert field…</option><option v-for="field in fields" :key="field.key" :value="field.key">{{field.label}}</option></select></div></label></div></div><label>Audience<select v-model="form.audience_type" @change="audienceTypeChanged"><option value="all">All {{isTelegram?'subscribers':'eligible contacts'}}</option><option value="selected">Selected {{isTelegram?'subscribers':'eligible contacts'}}</option><option value="filtered">Filtered audience</option></select></label>
<div v-if="form.audience_type==='filtered'" class="filter-builder"><div class="segment-tools"><label>Saved segment<select v-model="selectedSegmentId" @change="loadSavedSegment"><option value="">Build a one-off audience…</option><option v-for="segment in segments" :key="segment.id" :value="segment.id">{{segment.name}}</option></select></label><label>Segment name<input v-model="segmentName" maxlength="150" placeholder="e.g. Gauteng Retail Customers" @keyup.enter.prevent="selectedSegmentId?updateSegment():saveSegment()"/></label><div class="segment-actions"><button v-if="!selectedSegmentId" type="button" class="small-btn primary" :disabled="savingSegment||!segmentName.trim()" @click="saveSegment">{{savingSegment?'Saving…':'Save as segment'}}</button><button v-if="selectedSegmentId" type="button" class="small-btn primary" :disabled="savingSegment||!segmentName.trim()" @click="updateSegment">{{savingSegment?'Saving…':'Update saved'}}</button><button v-if="selectedSegmentId" type="button" class="small-btn danger" :disabled="savingSegment" @click="deleteSegment">Delete</button></div></div><div v-if="segmentChanged" class="segment-notice"><strong>Saved segment has changed since this draft was created.</strong><span>The draft is still using its original rules.</span><button type="button" class="small-btn" @click="reloadSegmentRules">Reload current segment rules</button></div><div v-if="segmentMissing" class="segment-notice warning"><strong>Saved segment is no longer available.</strong><span>This draft is still using its original audience rules.</span></div><div class="filter-head"><strong>Audience rules</strong><select v-model="form.audience_filter.logic" @change="scheduleAudiencePreview"><option value="and">Match ALL rules (AND)</option><option value="or">Match ANY rule (OR)</option></select></div><div v-for="(rule,index) in form.audience_filter.rules" :key="index" class="filter-rule"><select v-model="rule.field" @change="scheduleAudiencePreview"><optgroup :label="channelLabel+' fields'"><option v-for="field in systemFields" :key="field.key" :value="field.key">{{field.label}}</option></optgroup><optgroup v-if="customFields.length" label="Custom fields"><option v-for="field in customFields" :key="field.key" :value="field.key">{{field.label}}</option></optgroup></select><select v-model="rule.operator" @change="scheduleAudiencePreview"><option v-for="op in filterOperators" :key="op[0]" :value="op[0]">{{op[1]}}</option></select><input v-if="operatorNeedsValue(rule.operator)" v-model="rule.value" @input="scheduleAudiencePreview" placeholder="Value"/><span v-else class="filter-no-value">No value required</span><button type="button" class="small-btn danger" @click="removeAudienceRule(index)">×</button></div><button type="button" class="secondary add-rule" @click="addAudienceRule">+ Add rule</button><div class="audience-preview" :class="{empty:zeroFilteredAudience}"><strong>{{previewingAudience?'Checking…':audiencePreview.count+' matching recipient'+(audiencePreview.count===1?'':'s')}}</strong><span v-if="zeroFilteredAudience" class="audience-warning">No contacts match these rules. Adjust the filters before creating the draft.</span><div v-if="audiencePreview.contacts.length" class="preview-contacts"><span v-for="contact in audiencePreview.contacts.slice(0,8)" :key="contact.id">{{contact.name}}</span><small v-if="audiencePreview.count>8">+ {{audiencePreview.count-8}} more</small></div></div></div>
<div v-if="form.audience_type==='selected'" class="audience-box"><div class="audience-tools"><strong>{{form.contact_ids.length}} selected</strong><button type="button" class="link-btn" @click="toggleAll">{{form.contact_ids.length===audience.length?'Clear all':'Select all'}}</button></div><label v-for="contact in audience" :key="contact.id" class="recipient-check"><input v-model="form.contact_ids" type="checkbox" :value="contact.id"/><span>{{contact.name}}<small v-if="contact.username">@{{contact.username}}</small></span></label></div>
